/* 解析两种形式都合法：字符串（老数据）或结构化对象 {focus,approach,steps[],pitfalls}；对象缺字段时按缺失处理。 */
const optStr=(x,n)=>typeof x==='string'&&x.trim()&&x.length<=n?x:'';
function analysis(a){if(typeof a==='string')return str(a,6000,'解析');if(a&&typeof a==='object'&&!Array.isArray(a)){const o={focus:optStr(a.focus,2000),approach:optStr(a.approach,4000),steps:Array.isArray(a.steps)?a.steps.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.slice(0,2000)).slice(0,20):[],pitfalls:optStr(a.pitfalls,2000)};if(!o.focus&&!o.approach&&!o.steps.length&&!o.pitfalls)err('解析格式不正确');return o;}err('解析格式不正确');}
function analysisText(a){if(typeof a==='string')return a;if(a&&typeof a==='object'&&!Array.isArray(a)){const out=[];if(typeof a.focus==='string'&&a.focus.trim())out.push('考什么：'+a.focus.trim());if(typeof a.approach==='string'&&a.approach.trim())out.push('怎么想：'+a.approach.trim());const steps=(Array.isArray(a.steps)?a.steps:[]).filter(s=>typeof s==='string'&&s.trim());if(steps.length)out.push('分步详解：\n'+steps.map((s,i)=>(i+1)+'. '+s.trim()).join('\n'));if(typeof a.pitfalls==='string'&&a.pitfalls.trim())out.push('易错点：'+a.pitfalls.trim());return out.join('\n');}return '';}
function validate(p){
 if(p?.schema!=='chem-practice/2')err('请导入 chem-practice/2 格式的高中练习题包');
 const out={schema:p.schema,id:id(p.id),version:id(p.version),title:str(p.title,120,'标题'),description:str(p.description,1200,'简介'),topics:list(p.topics,20,80,'章节'),questions:[],sources:[]};
 if(!Array.isArray(p.questions)||!p.questions.length||p.questions.length>300)err('题包须含1–300题');
 const ids=new Set();
 out.questions=p.questions.map(q=>{
  const key=id(q.id);if(ids.has(key))err('题目ID重复');ids.add(key);
  if(!out.topics.includes(q.topic))err('章节不存在');if(!['single','multi','fill','experiment'].includes(q.type))err('不支持的题型');
  const r={id:key,topic:q.topic,type:q.type,title:str(q.title,160,'题名'),stem:str(q.stem,6000,'题干'),analysis:analysis(q.analysis),source:str(q.source,300,'来源'),level:str(q.level,40,'层次')};
  const points=n=>Number.isInteger(n)&&n>0&&n<=50?n:err('分值须为1–50的整数');r.points=points(q.points);
  if(['single','multi'].includes(r.type)){
   r.options=list(q.options,8,1500,'选项');if(r.options.length<2)err('选项至少两个');
   const index=n=>Number.isInteger(n)&&n>=0&&n<r.options.length?n:err('答案索引越界');
   r.answer=r.type==='single'?index(q.answer):Array.isArray(q.answer)&&q.answer.length&&q.answer.length<=r.options.length?[...new Set(q.answer.map(index))].sort((a,b)=>a-b):err('多选答案无效');
  }else{
   if(!Array.isArray(q.parts)||!q.parts.length||q.parts.length>12)err('须有1–12个小题');const pids=new Set();
   r.parts=q.parts.map(v=>{const k=id(v.id);if(pids.has(k))err('小题ID重复');pids.add(k);if(!['numeric','text','manual'].includes(v.kind))err('小题类型不正确');const f={id:k,kind:v.kind,prompt:str(v.prompt,2000,'小题'),points:points(v.points),unit:typeof v.unit==='string'&&v.unit.length<100?v.unit:'',rubric:typeof v.rubric==='string'?v.rubric.slice(0,4000):''};if(v.kind==='numeric'){if(!Number.isFinite(v.answer)||!Number.isFinite(v.tolerance)||v.tolerance<0||v.tolerance>1000)err('数值答案或容差无效');f.answer=v.answer;f.tolerance=v.tolerance;}else if(v.kind==='text')f.answer=list(v.answer,20,1000,'参考答案');else if(!f.rubric.trim())err('开放题须有核对量规');return f;});
   if(r.parts.reduce((s,x)=>s+x.points,0)!==r.points)err('总分与小题分值不一致');
  }return r;
 });
 out.sources=(Array.isArray(p.sources)?p.sources:[]).slice(0,8).map(s=>({title:str(s.title,160,'来源标题'),url:typeof s.url==='string'&&/^https:\/\//.test(s.url)&&s.url.length<500?s.url:err('链接须为HTTPS')}));return out;
}
function parse(raw){if(typeof raw!=='string'||raw.length>1000000)err('题包文本过大');raw=raw.replace(/^\uFEFF/,'');if(raw.trimStart().startsWith('{'))return validate(JSON.parse(raw));const b=[...raw.matchAll(/```chem-practice\s*\r?\n([\s\S]*?)\r?\n```/g)];if(b.length!==1)err('Markdown须包含唯一的chem-practice数据块');return validate(JSON.parse(b[0][1]));}
const norm=s=>String(s??'').normalize('NFKC').trim().replace(/\s+/g,'').replace(/[₀₁₂₃₄₅₆₇₈₉]/g,c=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(c)).replace(/⁺/g,'+').replace(/⁻|−/g,'-');
function part(f,v){if(f.kind==='manual')return {pending:true,score:0,max:0,manualMax:f.points};const raw=String(v??'').trim();if(!raw)return {valid:false,score:0,max:f.points};let correct=false;if(f.kind==='numeric'){if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(raw)||!Number.isFinite(Number(raw)))return {valid:false,score:0,max:f.points};correct=Math.abs(Number(raw)-f.answer)<=f.tolerance+Number.EPSILON*Math.max(1,Math.abs(f.answer))*8;}else correct=f.answer.some(a=>norm(a)===norm(raw));return {valid:true,correct,score:correct?f.points:0,max:f.points};}
function grade(q,answers){
 if(q.type==='single'){const v=answers.choice;if(!Number.isInteger(v)||v<0||v>=q.options.length)return {valid:false};return {valid:true,score:v===q.answer?q.points:0,max:q.points,pending:0,parts:[]};}
 if(q.type==='multi'){const a=answers.choice;if(!Array.isArray(a)||!a.length||a.some(v=>!Number.isInteger(v)||v<0||v>=q.options.length)||new Set(a).size!==a.length)return {valid:false};const right=a.every(x=>q.answer.includes(x)),full=right&&a.length===q.answer.length;return {valid:true,score:full?q.points:right?Math.floor(q.points/2):0,max:q.points,pending:0,parts:[]};}
 const ps=q.parts.map(f=>({id:f.id,...part(f,answers[f.id])}));return {valid:ps.every(x=>x.pending||x.valid),score:ps.reduce((n,x)=>n+x.score,0),max:ps.reduce((n,x)=>n+x.max,0),pending:ps.reduce((n,x)=>n+(x.manualMax||0),0),parts:ps};
}
