function analysisHTML(a){if(typeof a!=='object'||!a||Array.isArray(a))return `<p>${E(typeof a==='string'?a:'')}</p>`;const s=[];if(typeof a.focus==='string'&&a.focus.trim())s.push(`<p><b>考什么</b>　${E(a.focus)}</p>`);if(typeof a.approach==='string'&&a.approach.trim())s.push(`<p><b>怎么想</b>　${E(a.approach)}</p>`);const steps=(Array.isArray(a.steps)?a.steps:[]).filter(x=>typeof x==='string'&&x.trim());if(steps.length)s.push(`<p><b>分步详解</b></p><ol>${steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol>`);if(typeof a.pitfalls==='string'&&a.pitfalls.trim())s.push(`<p><b>易错点</b>　${E(a.pitfalls)}</p>`);return s.join('')||'<p>暂无解析。</p>';}
