function enter(){window.ChemGames?.stop();showHome();UI.view='practice';UI.sel=null;$('sidebar').classList.remove('show');$('mask').classList.remove('show');$('inspector').classList.remove('show');qid='';tab='list';onlyWrong=false;render();$('viewDoc').scrollTop=0;}
