function list(){const qs=pack.questions.filter(q=>(!topic||q.topic===topic)&&(!type||q.type===type)&&(!query||[q.title,q.stem,q.topic].join(' ').includes(query))&&(!onlyWrong||(records[q.id]?.result&&records[q.id].result.score<records[q.id].result.max)));return qs.map(q=>{const r=records[q.id];return `<button class="wb-row" data-pr="question" data-val="${E(q.id)}"><span class="wb-num">${String(pack.questions.indexOf(q)+1).padStart(2,'0')}</span><span class="wb-row-body"><strong>${E(q.title)}</strong><small>${E(q.topic)} · ${names[q.type]} · ${q.points}分</small></span><span class="wb-state">${r?.result?`${r.result.score}/${r.result.max}分${r.result.pending?' · 待核对':''}`:r&&Object.keys(r.answers).length?'继续作答':'未作答'} →</span></button>`;}).join('')||'<p class="wb-empty">这里还没有符合条件的题目。</p>';}
