function cache(){const q=current();if(!q)return;const d=draft(q);if(q.options){const checked=[...document.querySelectorAll('input[name=wbChoice]:checked')].map(x=>Number(x.value));d.answers.choice=q.type==='multi'?checked:checked[0]??null;}else q.parts.forEach(p=>{const el=$('wbf_'+p.id);if(el)d.answers[p.id]=el.value;});if($('wbReason'))d.reason=$('wbReason').value;save();}
