(function(root){'use strict';
const levels=[
 {name:'第一束光',size:5,source:[-1,3],direction:[1,0],detector:[5,1],sample:[3,1],color:'#6de9cd',mirrors:[[2,3],[2,1]],initial:['\\','/'],blocks:[[0,0],[4,4]]},
 {name:'折返实验',size:5,source:[-1,4],direction:[1,0],detector:[5,3],sample:[4,2],color:'#86c8ff',mirrors:[[1,4],[1,1],[4,1],[4,3]],initial:['\\','/','/','\\'],blocks:[[2,2],[0,0]]},
 {name:'六镜回廊',size:5,source:[-1,4],direction:[1,0],detector:[5,0],sample:[3,0],color:'#d5a6ff',mirrors:[[1,4],[1,1],[4,1],[4,3],[2,3],[2,0]],initial:['/','\\','\\','/','/','/'],blocks:[[0,0],[3,4]]}
];
function reflect(d,mirror){return mirror==='/'?[-d[1],-d[0]]:[d[1],d[0]];}
function trace(l,orient){let p=[...l.source],d=[...l.direction],sample=false,seen=new Set(),path=[[...p]];for(let i=0;i<100;i++){p=[p[0]+d[0],p[1]+d[1]];path.push([...p]);if(p[0]===l.detector[0]&&p[1]===l.detector[1])return {path,sample,won:sample,reason:sample?'detector':'no-sample'};if(p.some(n=>n<0||n>=l.size))return {path,sample,won:false,reason:'exit'};const key=p.join(',')+':'+d.join(',');if(seen.has(key))return {path,sample,won:false,reason:'loop'};seen.add(key);if(l.blocks.some(b=>b[0]===p[0]&&b[1]===p[1]))return {path,sample,won:false,reason:'blocked'};if(p[0]===l.sample[0]&&p[1]===l.sample[1])sample=true;const m=l.mirrors.findIndex(a=>a[0]===p[0]&&a[1]===p[1]);if(m>=0)d=reflect(d,orient[m]);}return {path,sample,won:false,reason:'limit'};}
const energy=n=>-13.6/(n*n),gap=n=>energy(n)-energy(2),wavelength=n=>1239.84/gap(n),lines=[{n:3,name:'红光',color:'#ff697d'},{n:4,name:'青蓝光',color:'#58dcff'},{n:5,name:'蓝紫光',color:'#9c9aff'},{n:6,name:'紫光',color:'#d58bff'}].map(l=>({...l,e:gap(l.n),nm:Math.round(wavelength(l.n))}));
function resonance(e){if(!Number.isFinite(e))return null;const l=[...lines].sort((a,b)=>Math.abs(a.e-e)-Math.abs(b.e-e))[0];return Math.abs(l.e-e)<=.045?l:null;}
root.ChemExtraRules={levels,reflect,trace,energy,gap,wavelength,lines,resonance};
})(typeof window==='undefined'?globalThis:window);

