 for(const o of this.objects.filter(x=>!x.ghost)){const p=this.project([o.p[0],-1.88,o.p[2]]);c.fillStyle='rgba(32,56,65,.08)';c.beginPath();c.ellipse(p.x,p.y,(o.r||.33)*this.scale*p.k,4*p.k,0,0,Math.PI*2);c.fill();}
 for(const b of this.bonds){const A=this.project(b[0]),B=this.project(b[1]);c.strokeStyle=dark?'#7bbbd0':'#b6c1c5';c.lineCap='round';c.lineWidth=8*Math.min(A.k,B.k);c.beginPath();c.moveTo(A.x,A.y);c.lineTo(B.x,B.y);c.stroke();if(b[2]===2){c.strokeStyle='#f4f7f7';c.lineWidth=2;c.beginPath();c.moveTo(A.x,A.y);c.lineTo(B.x,B.y);c.stroke();}}
