 function draw(){scene.objects=m().atoms.map(([a,x,y,z],i)=>({p:[x,y,z],r:a==='H'?.29:.43,ghost:!placed[i],label:placed[i]||'',color:atoms[a].color,ink:atoms[a].ink}));scene.palette=complete?null:Object.keys(atoms);scene.bonds=m().bonds.filter(([a,b])=>placed[a]&&placed[b]).map(([a,b,n])=>[m().atoms[a].slice(1),m().atoms[b].slice(1),n]);scene.message=complete?'✓ '+m().formula:'';scene.draw();}
 function place(i){if(!held){status('先从原子架取一个原子。');return;}if(rules.canPlace(m(),i,held)){placed[i]=held;window.ChemFX?.burst(scene,m().atoms[i].slice(1),atoms[held].color);held=null;scene.drag=null;status('连接成功。再找下一个成键位置。');sync();}else{status(i===0?'这个原子不适合作为当前分子的中心，换一个试试。':'这不是当前分子在该位置需要的原子，再看一眼化学式。');scene.drag=null;draw();}}
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};};
 const near=(p,objects,radius=30)=>objects.map((o,i)=>({i,p:scene.project(o.p)})).map(o=>({...o,d:Math.hypot(o.p.x-p.x,o.p.y-p.y)})).filter(o=>o.d<radius).sort((a,b)=>a.d-b.d)[0]?.i;
 canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);const p=point(e),sup=scene.palette||[],si=sup.findIndex((a,i)=>Math.hypot(p.x-(i+1)*scene.w/5,p.y-(scene.h-78))<30),slot=near(p,m().atoms.map(a=>({p:a.slice(1)})),35);if(si>=0){held=sup[si];dragging=true;scene.drag={atom:held,...p};sync();}else if(held&&slot!==undefined)place(slot);else if(slot!==undefined&&placed[slot]){held=placed[slot];delete placed[slot];dragging=true;scene.drag={atom:held,...p};sync();}else{orbit=true;lastX=e.clientX;}},{signal:abort.signal});
 canvas.addEventListener('pointermove',e=>{if(orbit){scene.yaw+=(e.clientX-lastX)*.012;lastX=e.clientX;draw();}else if(dragging){scene.drag={atom:held,...point(e)};draw();}},{signal:abort.signal});
