/* 数量标签：为 0 时隐藏（错题本计数） */
(function(){
  function norm(){
    var el=document.getElementById('mistakeCount');
    if(!el)return;
    var v=(el.textContent||'').trim();
    el.classList.toggle('hide-zero', v===''||v==='0');
  }
  norm();
  var t=null;
  new MutationObserver(function(){clearTimeout(t);t=setTimeout(norm,30);})
    .observe(document.body,{subtree:true,childList:true,characterData:true});
})();

/* 导航重排：拆掉包装 div，按固定优先级重排 */
(function(){
  var RANK=[['doc','home',10],['cw-action','center',11],['study-enter','lesson',12],['study-enter','solve',13],['cw-kind','exp',14],['lab','practice',20],['mod','exps',30],['mod','subs',40],['mod','apps',60],
            ['mod','mols',70],['teach','mistakes',80],['teach','lessons',90],['lab','games',100],['pt','1',110],['doc','bp',120]];
  function rankOf(el){
    var b=el.querySelector?el.querySelector('.nav-cat'):null;
    if(!b)return 999;
    for(var i=0;i<RANK.length;i++){
      var k=RANK[i][0],v=RANK[i][1];
      if(k==='pt'){if(b.hasAttribute('data-pt'))return RANK[i][2];}
      else if((b.getAttribute('data-'+k)||'')===v)return RANK[i][2];
    }
    return 900;
  }
  window.reorderNav=function(){
    var t=document.getElementById('navTree');if(!t)return;
    /* 拆掉非 .nav-group 的包装层 */
    Array.prototype.slice.call(t.children).forEach(function(c){
      if(!c.classList.contains('nav-group')){
        Array.prototype.slice.call(c.children).forEach(function(g){t.insertBefore(g,c);});
        if(c.parentNode===t)t.removeChild(c);
      }
    });
    Array.prototype.slice.call(t.children)
      .sort(function(a,b){return rankOf(a)-rankOf(b);})
      .forEach(function(el){t.appendChild(el);});
  };
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){setTimeout(window.reorderNav,0);});
  }else{setTimeout(window.reorderNav,0);}
  setTimeout(window.reorderNav,400);
  setTimeout(window.reorderNav,1200);
})();

/* 顶栏元素周期表入口；点击标题回到工作台 */
(function(){
  function bind(){
    var b=document.getElementById('btnPT');
    if(b&&!b._bound){
      b._bound=true;
      b.addEventListener('click',function(){
        var t=document.querySelector('#navTree [data-pt]');
        if(t)t.click();
      });
    }
    var br=document.querySelector('.brand');
    if(br&&!br._bound){
      br._bound=true;
      br.addEventListener('click',function(){
        var h=document.querySelector('#navTree [data-doc="home"]');
        if(h)h.click();
      });
    }
  }
  bind();
  setTimeout(bind,300);
  setTimeout(bind,1200);
})();
